import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a in me if a == 'C')
    my_d = n - my_c

    # Hard endgame: if opponent rarely defects, take free points late.
    if n >= 92:
        if opp_d <= 2:
            return 'D'
        if opp_d <= max(3, n // 25):
            return 'D'
        if opp[-1] == 'D' and n >= 96:
            return 'D'
        return 'C'

    # Persistent all-defector: cut losses but probe occasionally.
    if opp_d == n and n >= 4:
        if n < 90 and rng.random() < 0.06:
            return 'C'
        return 'D'

    # Very persistent defector, but not purely so: mostly defect, rare probe.
    if opp_d >= n - 1 and n >= 6:
        if opp[-1] == 'C':
            return 'C'
        if n < 90 and rng.random() < 0.07:
            return 'C'
        return 'D'

    # Strongly cooperative opponent: preserve mutual cooperation,
    # but do occasional light probes early so pure cooperators get exploited.
    if opp_d == 0:
        if n < 40:
            if n >= 4 and rng.random() < 0.025:
                return 'D'
        elif n < 80:
            if rng.random() < 0.02:
                return 'D'
        return 'C'

    if opp_d <= max(1, n // 20):
        if opp[-1] == 'D':
            # single rare defection: one retaliatory move, then forgive
            if opp_d <= 2:
                return 'D'
            return 'C'
        return 'C'

    # Higher-defection regimes: adaptively retaliate, but avoid permanent DD lock.
    recent = history[-8:] if n >= 8 else history
    r_opp_d = sum(1 for x in recent if x[1] == 'D')
    r_opp_c = len(recent) - r_opp_d
    r_me_d = sum(1 for x in recent if x[0] == 'D')
    r_me_c = len(recent) - r_me_d

    # If mutual defection dominates recently, attempt repair with cooperate.
    if r_opp_d >= 5 and r_me_d >= 5:
        if rng.random() < 0.75:
            return 'C'

    # If opponent has been alternating or mostly defecting but recently showed C,
    # try to rebuild cooperation after a short punishment.
    if r_opp_d >= 4 and opp[-1] == 'C':
        if rng.random() < 0.6:
            return 'C'

    # Exploit pattern: we defect, they cooperate. Keep exploiting moderately.
    if me and me[-1] == 'D' and opp[-1] == 'C':
        if my_d > my_c and rng.random() < 0.55:
            return 'D'
        return 'C'

    # Last opponent move logic, with forgiveness and clear signals.
    last_opp = opp[-1]
    last_me = me[-1]

    if last_opp == 'D':
        if last_me == 'D':
            # We just punished; return to C to give a chance to restore cooperation
            # unless opponent is clearly aggressive.
            if r_opp_d >= 4:
                return 'D'
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        # Opponent defected against our cooperation: retaliate once.
        return 'D'

    # Last opponent cooperated.
    if last_me == 'D':
        # We defected and they still cooperated; be careful not to over-exploit
        # a reciprocal opponent.
        return 'C'

    # Both cooperated last round. Occasionally defect against suspiciously
    # cooperative opponents only if we can detect a benefit; otherwise keep CC.
    if n >= 20 and opp_d * 5 < n:
        # very cooperative: small late-ish probing already handled above
        return 'C'

    # Mid opponents: mostly cooperate with sparse pressure to avoid being farmed.
    if n < 90 and rng.random() < 0.03:
        return 'D'
    return 'C'
